local function chip(order, art, txt, lead)
	if not lead then
		local rail = new("Frame", {
			Name = rnd(),
			Size = UDim2.fromOffset(14, 16),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			LayoutOrder = order,
