			end
		end)

		local api = {}

		local function crate(col, fixed)
			col.n += 1

			local slot = new("Frame", {
				Name = rnd(),
				Size = UDim2.new(1, 0, 0, fixed or 0),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
