local __FACTORIES = {};
local __CACHE = {};
local __NIL = {};

local function require(moduleName)
	if type(moduleName) ~= "string" then
		error("require: module name must be a string, got " .. type(moduleName), 2);
	end;
	local cached = __CACHE[moduleName];
	if cached == __NIL then return nil; end;
	if cached ~= nil then return cached; end;
	local source = __SOURCES[moduleName];
	if source ~= nil then
		__CACHE[moduleName] = source;
		return source;
	end;
	local factory = __FACTORIES[moduleName];
	if not factory then
		error("require: module '" .. moduleName .. "' is not registered in this bundle", 2);
	end;
	local result = factory();
	__CACHE[moduleName] = (result == nil) and __NIL or result;
	return result;
end;

