		failedUntil[original] = os.clock() + 15;
		Remote.Status.lastIssue = "asset HTTP failed or timed out";
		return nil;
	end;

	local function download(url, seconds)
		if not Remote.current() or (failedUntil[url] or 0) > os.clock() then return nil end;
