			task.spawn(function() pcall(kill, path) end);
			return true;
		end;
		local ok = Remote.io(function() return kill(path) end);
		if not ok then return false end;
		if type(isfile) == "function" then
			local checked, exists;
			if unloading then checked, exists = pcall(isfile, path)
			else checked, exists = Remote.io(function() return isfile(path) end) end;
			if not checked or exists then return false end;
		end;
		temporary[path] = nil;
		Remote.Status.removed += 1;
		return true;
	end;
	local function writeAsset(path, body)
		return Remote.io(function()
			writefile(path, body);

			if not Remote.current() or Remote.Status.cacheBlocked then drop(path, true) end;
		end);
	end;
	function Remote.purge()
		if type(listfiles) ~= "function" or type(isfolder) ~= "function" then return end;
		local media = { png=true, jpg=true, jpeg=true, webp=true, gif=true, bmp=true, wav=true, ogg=true, mp3=true };
		local catalogues = {};
		for _, rel in ipairs({ "animpacks.json", "emotes.json" }) do
			catalogues[string.match(Remote.file(rel), "([^/]+)$")] = true;
		end;
		for _, folder in ipairs({ "Salad Visuals/.data", "Salad Visuals/.data-v2" }) do
			local ok, exists = Remote.io(function() return isfolder(folder) end);
			if not ok or not exists then continue end;
			local fine, files = Remote.io(function() return listfiles(folder) end);
			if not fine or type(files) ~= "table" then continue end;
			for _, file in ipairs(files) do
				local name = tostring(file):gsub("\\", "/"):match("([^/]+)$");
				local path = name and (folder .. "/" .. name);
				local first, second, ext;
				if name then first, second, ext = name:match("^(%x+)%-(%x+)%.(%w+)$") end;
				local old = first and (#first == 20 or #first == 28)
					and (#second == 20 or #second == 28 or #second == 64) and ext ~= "json" and ext ~= "txt";
				local repairFirst, repairSecond, repairExt;
				if name then
					repairFirst, repairSecond, repairExt = name:match("^(%x+)%-(%x+)%-repair%-%d+%-%d+%.(%w+)$");
				end;
				local repair = repairFirst and (#repairFirst == 20 or #repairFirst == 28)
					and (#repairSecond == 20 or #repairSecond == 28 or #repairSecond == 64)
					and media[(repairExt or ""):lower()];
				local logical, extension;
				if name then logical, extension = name:match("^(%x+)%.(%w+)$") end;
				if logical and (#logical == 20 or #logical == 28) and media[(extension or ""):lower()] then old = true end;
				if logical and (#logical == 20 or #logical == 28) and (extension == "json" or extension == "txt")
					and not catalogues[name] then old = true end;
