			end;
			expected += size;
			names[rel] = true;
			if index % 8 == 0 then
				task.wait();
				if not ALIVE or GLOBAL.__VisualsGeneration ~= INIT_GENERATION then return 0, 1 end;
			end;
		end;
		if expected ~= #blob - at then return 0, 1 end;
		Remote.catalog = Remote.catalog or {};
		for rel in pairs(names) do Remote.catalog[rel] = true end;
		local done, failed, lastPct = 0, 0, 0;

		for index = 1, total do
			if not ALIVE or GLOBAL.__VisualsGeneration ~= INIT_GENERATION then settle(); return done, failed end;
			local entry = list[index];
			local rel, offset, size = entry[1], entry[2], entry[3];
			local body = string.sub(blob, at + offset + 1, at + offset + size);

			local kept;

			if isData(rel) then
				bodies[rel] = body;
				kept = true;
			else
				if not ids[rel] then pendingAssets[rel] = body; retryAfter[rel] = nil end;
				kept = true;
			end;

			if kept then done = done + 1 else failed = failed + 1 end;

			local pct = math.floor(index / total * 10);

			if pct > lastPct then
				lastPct = pct;

				if report then report(index, total) end;

				task.wait();
			end;
		end;

		settle();

		Remote.Status.failed = failed;
		return done, failed;
	end;
	local MEDIA = { png = true, jpg = true, jpeg = true, ogg = true, wav = true, mp3 = true };
	function Remote.registerAll()
		local list = {};
		for rel in pairs(pendingAssets) do
			local ext = string.lower(string.match(rel, "%.(%w+)$") or "");

			if MEDIA[ext] and string.sub(rel, 1, 9) ~= "skyboxes/" then list[#list + 1] = rel end;
		end;
		table.sort(list);
		for _, rel in ipairs(list) do
			if not Remote.current() then return end;
			local finish = Remote.busy();
			pcall(Remote.asset, rel);
			finish();
			task.wait();
		end;
	end;

	onUnload("asset cache", function()
		for path in pairs(temporary) do drop(path, true) end;
		table.clear(held); table.clear(temporary);
		table.clear(pendingAssets); table.clear(bodies); table.clear(ids); table.clear(byPath);
	end);
end;

local USER_DATA = "Salad Visuals/.data";
local function userFile(name)
	local path, old = USER_DATA .. "/" .. name, "Salad Visuals/Config/" .. name;
	if not (isfile and readfile and writefile) then return path end;
	pcall(function()
		if not isfile(old) then return end;
		if not isfile(path) then
			if isfolder and makefolder and not isfolder(USER_DATA) then makefolder(USER_DATA) end;
			writefile(path, readfile(old));
		end;
		local kill = delfile or delete_file;
		if kill and isfile(path) then kill(old) end;
	end);
	return path;
end;

function Remote.bootstrap()
	if Remote.base == "" then return end;
	local started = os.clock();
	Remote.Status.stage = "fetching";
	pcall(Remote.purge);

	local failed, pending = 0, 0;
	for _, pack in ipairs({ "bundle.pack", "sky.pack" }) do
		pending += 1;
		task.spawn(function()
			local ok, _, missing = pcall(Remote.sync, pack);
			if not ok or (missing or 0) > 0 then
				failed += 1;
				warn("[visuals] " .. pack .. " unavailable; files will be fetched one by one");
			end;
			pending -= 1;
		end);
	end;
	while pending > 0 and Remote.current() do task.wait(0.1) end;

	Remote.Status.failed = failed;
	Remote.Status.stage = failed == 0 and "ready" or "failed";
	if failed > 0 then Remote.Status.lastIssue = "asset pack unavailable; individual downloads remain available" end;
	if Remote.current() then Remote.registerAll() end;
	Remote.Status.elapsed = os.clock() - started;
end;

