	Default = S.ChamsOutline, Flag = "chams_outline",
	Callback = function(v) S.ChamsOutline = v end,
});
glowOutline:AddSlider({
	Min = 0, Max = 100, Default = 0, Type = "%", Size = 80,
	Flag = "chams_outline_t",
