	local FX = { Catalog = CATALOG, ById = {}, Loaded = {} };
	ESP.GameFX = FX;
	for _, entry in ipairs(CATALOG) do FX.ById[entry.id] = entry end;

	local REF = {};
	local ENVIRONMENT = {
		math = math,
		R = function(i) return setmetatable({ i }, REF) end,
		V3 = Vector3.new, V2 = Vector2.new, C3 = Color3.new, CF = CFrame.new,
		BC = function(n) return BrickColor.new(n) end,
		UD = function(s, o) return UDim.new(s, o) end,
		UD2 = function(a, b, c, d) return UDim2.new(a, b, c, d) end,
		RC = function(a, b, c, d) return Rect.new(a, b, c, d) end,
		NR = function(a, b) return NumberRange.new(a, b) end,
		E = function(t, n)
			local ok, v = pcall(function() return Enum[t][n] end);
			return ok and v or nil;
		end,
		CS = function(t)
			local k = {};
			for i = 1, #t, 4 do k[#k + 1] = ColorSequenceKeypoint.new(t[i], Color3.new(t[i + 1], t[i + 2], t[i + 3])) end;
			return ColorSequence.new(k);
		end,
		NS = function(t)
			local k = {};
			for i = 1, #t, 3 do k[#k + 1] = NumberSequenceKeypoint.new(t[i], t[i + 1], t[i + 2]) end;
			return NumberSequence.new(k);
		end,
		FT = function(family, weight, style)
			local ok, f = pcall(Font.new, family, Enum.FontWeight[weight], Enum.FontStyle[style]);
			return ok and f or nil;
		end,
		FC = function(names)
			local list = {};
			for _, n in ipairs(names) do list[#list + 1] = Enum.NormalId[n] end;
			return Faces.new(unpack(list));
		end,
		AX = function(names)
			local list = {};
			for _, n in ipairs(names) do list[#list + 1] = Enum.Axis[n] end;
			return Axes.new(unpack(list));
		end,
		PP = function(d, f, e, fw, ew) return PhysicalProperties.new(d, f, e, fw, ew) end,
	};

	local loading = {};
	local function loadGame(name)
		if FX.Loaded[name] then return FX.Loaded[name] end;
		if loading[name] then
			local deadline = os.clock() + 60;
			repeat task.wait(0.05) until not loading[name] or not ALIVE or os.clock() > deadline;
			return FX.Loaded[name];
		end;
		loading[name] = true;
		local ok, result = pcall(function()

			local body;
			local path = "fxdata/" .. name .. ".lua";
			if isfile and readfile then
				local okF, has = pcall(isfile, path);
				if okF and has then
					local okR, text = pcall(readfile, path);
					if okR then body = text end;
				end;
			end;
			body = body or Remote.body("fx/" .. name .. ".bin");
			if type(body) ~= "string" or body:sub(1, 7) ~= "return " then error("fx/" .. name .. ".bin did not arrive") end;
			local chunk, err = loadstring(body, "@fx_" .. name);
			if not chunk then error(err) end;
			setfenv(chunk, setmetatable({}, { __index = ENVIRONMENT }));
			local data = chunk();
			local byId = {};
			for _, item in ipairs(data.items) do byId[item.id] = item end;
			return byId;
		end);
		loading[name] = nil;
		if not ok then recordError("game fx " .. name .. ": " .. tostring(result)); return nil end;
		FX.Loaded[name] = result;
		return result;
	end;

	local ALIAS = { LeftArm = "Left Arm", RightArm = "Right Arm", LeftLeg = "Left Leg", RightLeg = "Right Leg" };
	local R15 = {
		Torso = "UpperTorso",
		["Left Arm"] = "LeftUpperArm", ["Right Arm"] = "RightUpperArm",
		["Left Leg"] = "LeftUpperLeg", ["Right Leg"] = "RightUpperLeg",
	};

	local function limb(char, name)
		name = ALIAS[name] or name;
		local p = char:FindFirstChild(name);
		if p and p:IsA("BasePart") then return p, CFrame.new() end;

		if name == "HumanoidRootPart" then return limb(char, "Torso") end;
		local stand = R15[name];
		local q = stand and char:FindFirstChild(stand);
		if not (q and q:IsA("BasePart")) then return nil end;
		if name == "Torso" then
			local root = char:FindFirstChild("HumanoidRootPart");
			return q, CFrame.new(root and q.CFrame:PointToObjectSpace(root.Position) or Vector3.zero);
		end;
		return q, CFrame.new(0, -q.Size.Y / 2, 0);
	end;

	local R6_BODY = { "Torso", "Right Arm", "Left Arm", "Right Leg", "Left Leg", "Head" };
	local function bodyParts(char)
		local out = {};
		for _, n in ipairs(R6_BODY) do
			local p = char:FindFirstChild(n);
			if p and p:IsA("BasePart") then out[#out + 1] = p end;
		end;
		if #out <= 1 then
			for _, p in ipairs(char:GetChildren()) do
				if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and not table.find(out, p) then out[#out + 1] = p end;
			end;
		end;
		return out;
	end;

	local function shown(m)
		local torso = m and (m:FindFirstChild("Torso") or m:FindFirstChild("UpperTorso") or m:FindFirstChild("HumanoidRootPart"));
		return torso ~= nil and torso:IsA("BasePart");
	end;
	local function drawn(m)
		for _, n in ipairs({ "Torso", "UpperTorso", "Head" }) do
			local p = m:FindFirstChild(n);
			if p and p:IsA("BasePart") and p.Transparency < 1 then return true end;
		end;
		return false;
	end;
	local function wearer()
		local char = LocalPlayer.Character;
		local rigs = workspace:FindFirstChild("Rigs");
		local rig = rigs and rigs:FindFirstChild(LocalPlayer.Name);
		if char and char.Parent and shown(char) and drawn(char) then return char end;
		if rig and rig:IsA("Model") and shown(rig) then return rig end;
		if char and char.Parent and shown(char) then return char end;
		return nil;
	end;
	FX.Wearer = wearer;

	local meshCache = {};
	local function meshPart(id, initial)
		local base = meshCache[id];
		if not base then
			local ok, made = pcall(AssetService.CreateMeshPartAsync, AssetService, id);
			if not ok or not made then
				made = Instance.new("MeshPart");
				pcall(function() made.MeshId = id end);
				if initial and sethiddenproperty then pcall(sethiddenproperty, made, "InitialSize", initial) end;
			end;
			meshCache[id] = made;
			base = made;
		end;
		return base:Clone();
	end;

	local function build(node, ctx)
		if node.limb then
			local target = limb(ctx.char, node.n);
			if not target then return nil end;
			ctx.map[node.i] = target;
			for _, c in ipairs(node.k or {}) do
				local child = build(c, ctx);
				if child then ctx.limbKids[#ctx.limbKids + 1] = { child, target, node.cf } end;
			end;
			return nil;
		end;
		local inst;
		if node.c == "MeshPart" and node.m and node.m ~= "" then
			inst = meshPart(node.m, node.z);
		else
			local ok, made = pcall(Instance.new, node.c);
			if not ok then return nil end;
			inst = made;
		end;
		inst.Name = node.n;
		ctx.map[node.i] = inst;
		for k, v in pairs(node.p) do
			if getmetatable(v) == REF then
				ctx.refs[#ctx.refs + 1] = { inst, k, v[1] };
			else
				pcall(function() inst[k] = v end);
			end;
		end;
		if node.a then
			for k, v in pairs(node.a) do pcall(inst.SetAttribute, inst, k, v) end;
		end;
		if inst:IsA("BasePart") then

			inst.Anchored, inst.CanCollide, inst.CanTouch, inst.CanQuery = false, false, false, false;
			inst.Massless = true;
		end;
		for _, c in ipairs(node.k or {}) do
			if c.c == "SurfaceAppearance" then

				local map = c.p.ColorMap;
				if inst:IsA("MeshPart") and type(map) == "string" and map ~= "" and inst.TextureID == "" then
					pcall(function() inst.TextureID = map end);
				end;
			else
				local child = build(c, ctx);
				if child then child.Parent = inst end;
			end;
		end;
		return inst;
	end;

	local function partsUnder(root)
		local out = root:IsA("BasePart") and { root } or {};
		for _, d in ipairs(root:GetDescendants()) do
			if d:IsA("BasePart") then out[#out + 1] = d end;
		end;
		return out;
	end;

	local tuning = { aura = {}, trail = {}, cosmetic = {} };

	local function remember(l, roots)
		local list = {};
		local function note(d)
			if d:IsA("ParticleEmitter") then
				list[#list + 1] = { d, rate = d.Rate, bright = d.Brightness, size = d.Size, speed = d.Speed,
					spin = d.RotSpeed, life = d.Lifetime, color = d.Color };
			elseif d:IsA("Beam") then
				list[#list + 1] = { d, color = d.Color, bright = d.Brightness };
			elseif d:IsA("Trail") then
				list[#list + 1] = { d, color = d.Color, life = d.Lifetime, bright = d.Brightness };
			elseif d:IsA("Light") then
				list[#list + 1] = { d, color = d.Color, bright = d.Brightness };
			elseif (d:IsA("BasePart") or d:IsA("Decal")) and d.Transparency < 1 then
				list[#list + 1] = { d, transparency = d.Transparency, color = d:IsA("Decal") and d.Color3 or d.Color,
					texture = d:IsA("MeshPart") and d.TextureID or nil };
			end;
		end;
		for _, r in ipairs(roots) do
			note(r);
			for _, d in ipairs(r:GetDescendants()) do note(d) end;
		end;
		l.tune = list;
	end;

	local function scaled(sequence, factor)
		if factor == 1 then return sequence end;
		local points = {};
		for i, k in ipairs(sequence.Keypoints) do
			points[i] = NumberSequenceKeypoint.new(k.Time, k.Value * factor, k.Envelope * factor);
		end;
		return NumberSequence.new(points);
	end;

	local function movedFrame(frame, offset, scale)
		return CFrame.new(frame.Position * scale + offset) * (frame - frame.Position);
	end;

	local function captureCosmeticTransforms(l)
		l.transforms = {};

		local ours, mine = {}, {};
		for _, object in ipairs(l.worn or {}) do
			ours[object] = true;
			mine[#mine + 1] = object;
			for _, d in ipairs(object:GetDescendants()) do
				ours[d] = true;
				mine[#mine + 1] = d;
			end;
		end;

		for _, object in ipairs(mine) do
			if object:IsA("BasePart") then
				local mesh = object:FindFirstChildOfClass("SpecialMesh");
				local hang, firstSide;

				for _, joint in ipairs(object:GetJoints()) do
					if joint:IsA("Weld") or joint:IsA("Motor6D") then
						local far = (joint.Part0 == object) and joint.Part1 or joint.Part0;

						if far and not ours[far] then
							hang, firstSide = joint, joint.Part0 == object;
							break;
						end;
					end;
				end;

				l.transforms[object] = {
					kind = "part", cframe = object.CFrame, size = object.Size,
					mesh = mesh, meshScale = mesh and mesh.Scale or nil,
					joint = hang, first = firstSide,
					c0 = hang and hang.C0 or CFrame.new(), c1 = hang and hang.C1 or CFrame.new(),
				};
			elseif object:IsA("Attachment") then
				l.transforms[object] = { kind = "attachment", cframe = object.CFrame };
			end;
		end;
	end;

	local function applyCosmeticTransforms(l, t)
		if l.group ~= "cosmetic" then return end;

		local offset = Vector3.new(tonumber(t.x) or 0, tonumber(t.y) or 0, tonumber(t.z) or 0);
		local scale = math.clamp(tonumber(t.scale) or 1, 0.25, 2.5);

		for object, base in pairs(l.transforms or {}) do
			if object.Parent then
				pcall(function()
					if base.kind == "attachment" then
						object.CFrame = movedFrame(base.cframe, offset, scale);
						return;
					end;

					object.Size = base.size * scale;
					if base.mesh and base.mesh.Parent and base.meshScale then base.mesh.Scale = base.meshScale * scale end;

					local joint = base.joint;

					if joint and joint.Parent then

						if base.first then
							joint.C1 = movedFrame(base.c1, offset, scale);
						else
							joint.C0 = movedFrame(base.c0, offset, scale);
						end;
					end;
				end);
			end;
		end;
	end;

	local function applyTune(l)
		local t = tuning[l.group] or {};
		local glow, rate, amount, size, speed, life = t.glow or 1, t.rate or 1, t.amount or 1, t.size or 1, t.speed or 1, t.life or 1;
		local opacity = t.opacity or 1;
		local color = t.color;
		for _, r in ipairs(l.tune or {}) do
			local d = r[1];
			if d.Parent then
				pcall(function()
					if d:IsA("ParticleEmitter") then
						d.Rate = r.rate * rate * amount;
						d.Brightness = r.bright * glow;
						d.Size = scaled(r.size, size);
						local s = math.clamp(speed, 0.05, 5);
						d.Speed = NumberRange.new(r.speed.Min * s, r.speed.Max * s);
						d.RotSpeed = NumberRange.new(r.spin.Min * s, r.spin.Max * s);
						d.Lifetime = NumberRange.new(math.max(0.05, r.life.Min * life / s), math.max(0.06, r.life.Max * life / s));
						d.Color = color or r.color;
					elseif d:IsA("Trail") then
						d.Color = color or r.color;
						d.Lifetime = math.max(0.05, r.life * life);
						d.Brightness = r.bright * glow;
					elseif d:IsA("Beam") then
						d.Color = color or r.color;
						d.Brightness = r.bright * glow;
					elseif d:IsA("BasePart") or d:IsA("Decal") then
						d.Transparency = 1 - (1 - r.transparency) * opacity;

						local tint = color and color.Keypoints[1].Value;
						if d:IsA("Decal") then d.Color3 = tint or r.color
						else
							d.Color = tint or r.color;
							if r.texture then d.TextureID = tint and "" or r.texture end;
						end;
					else
						d.Color = color and color.Keypoints[1].Value or r.color;
						d.Brightness = r.bright * glow;
					end;
				end);
			end;
		end;
		applyCosmeticTransforms(l, t);
	end;

	local PORTS = {};

	PORTS["Echo/DistortionThing"] = function(ctx)
		local Torso = ctx.limb("Torso")
		local holder = ctx.live.roots.Torso
		local mesh = holder and holder:WaitForChild("EchoBubbleMesh", 5)
		if not (Torso and mesh) then return end
		local folder = workspace:FindFirstChild(ctx.player.Name .. "_distortion") or Instance.new("Folder")
		folder.Name = ctx.player.Name .. "_distortion"
		folder.Parent = workspace
		ctx.made(folder)
		local acc = 5
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			acc = acc + dt
			if acc < 4 then return end
			acc = 0
			if not Torso or Torso.Parent == nil then return end
			local bubble = mesh:Clone()
			bubble.CFrame = Torso.CFrame
			bubble.Anchored, bubble.CanCollide, bubble.CanTouch, bubble.CanQuery = false, false, false, false
			local weld = bubble:FindFirstChild("Weld")
			if weld then weld.Part0, weld.Part1 = Torso, bubble end
			bubble.Massless = true
			bubble.Parent = folder
			bubble.Material = Enum.Material.Glass
			bubble.Size = Vector3.new(6, 6, 6)
			bubble.Transparency = 1
			local hl = Instance.new("Highlight")
			hl.Enabled = false
			hl.Parent = bubble
			game:GetService("Debris"):AddItem(bubble, 11)
			TweenService:Create(bubble, TweenInfo.new(3, Enum.EasingStyle.Sine, Enum.EasingDirection.In), {
				Transparency = 6, Size = Vector3.new(7, 7, 7),
			}):Play()
			task.delay(2, function()
				if bubble.Parent then
					TweenService:Create(bubble, TweenInfo.new(8, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {
						Transparency = 1, Size = Vector3.new(8, 8, 8),
					}):Play()
				end
			end)
		end))
	end

	PORTS["RNS_Ring/TorsoRecolor"] = function(ctx)
		local holder = ctx.live.roots.HumanoidRootPart
		local main = holder and holder:WaitForChild("Main", 5)
		if not main then return end
		local colours = ctx.char:FindFirstChild("Body Colors") or ctx.char:FindFirstChildOfClass("BodyColors")
		local torso = ctx.limb("Torso")
		local c = (colours and colours.TorsoColor3) or (torso and torso.Color) or Color3.new(1, 1, 1)
		for _, d in ipairs(main:GetDescendants()) do
			if d:IsA("ParticleEmitter") then d.Color = ColorSequence.new(c) end
		end
	end

	local function hideLimbs(ctx, dropAccessories)
		for _, p in ipairs(bodyParts(ctx.char)) do
			if p.Name ~= "Head" then
				local was = p.Transparency
				p.Transparency = 1
				ctx.undo(function() if p.Parent then p.Transparency = was end end)
			end
		end
		if dropAccessories then

			for _, acc in ipairs(ctx.char:GetChildren()) do
				if acc:IsA("Accessory") then
					for _, d in ipairs(acc:GetDescendants()) do
						if d:IsA("BasePart") or d:IsA("Decal") then
							local was = d.Transparency
							d.Transparency = 1
							ctx.undo(function() if d.Parent then d.Transparency = was end end)
						end
					end
				end
			end
		end
	end
	PORTS["Voidbroken/Body"] = function(ctx) hideLimbs(ctx, false) end
	PORTS["VoidbrokenFull/Body"] = function(ctx) hideLimbs(ctx, true) end

	PORTS["MartOrbit/MartOrbitHandler"] = function(ctx)
		local p = ctx.parent
		local spin = { ["1"] = 1.2, ["2"] = 1.8, ["3"] = 1.6, ["4"] = 1.9, ["5"] = 1.3 }
		local rings = {}
		for name, rate in pairs(spin) do
			local a = p:FindFirstChild(name)
			if a then rings[a] = { rate, a.CFrame } end
		end
		local t = Vector3.zero
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			t = t + Vector3.new(math.pi, math.pi, math.pi) * dt
			for a, v in pairs(rings) do
				a.CFrame = v[2] * CFrame.Angles(t.X / 1e19, t.Y / v[1], 0)
			end
		end))
	end

	PORTS["SparklyDuet/SparklyDuetHandler"] = function(ctx)
		local p = ctx.parent
		local a = p:FindFirstChild("1") and p["1"]:FindFirstChild("1Number")
		local b = p:FindFirstChild("2") and p["2"]:FindFirstChild("2Number")
		if not (a and b) then return end
		local t = Vector3.zero
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			t = t + Vector3.new(math.pi, math.pi, math.pi) * dt
			local turn = CFrame.Angles(t.X / 4, t.Y / 2, 0)
			a.CFrame = a.CFrame * turn
			b.CFrame = b.CFrame * turn
		end))
	end

	local function pathTrail(first, second)
		return function(ctx)
			local root = ctx.char:WaitForChild("HumanoidRootPart", 5)
			local hum = ctx.char:WaitForChild("Humanoid", 5)
			local holder = ctx.live.roots.HumanoidRootPart
			local path = holder and holder:WaitForChild("Main", 5)
			path = path and path:WaitForChild("Path", 5)
			local a = path and path:WaitForChild(first, 5)
			local b = path and path:WaitForChild(second, 5)
			if not (root and hum and a and b) then return end
			local rate = a.Rate
			local conn
			conn = ctx.conn(RunService.RenderStepped:Connect(function()
				if hum:GetState() == Enum.HumanoidStateType.Dead or not (a.Parent and b.Parent) then
					conn:Disconnect()
					return
				end
				local running = hum:GetState() == Enum.HumanoidStateType.Running
				a.Enabled, b.Enabled = running, running
				local r = math.min((root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)).Magnitude * 2, rate)
				r = r <= 3 and 0 or r
				a.Rate, b.Rate = r, r
			end))
		end
	end
	PORTS["GuardianTrail/GuardianTrailScript"] = pathTrail("Blue", "Red")
	PORTS["BloomingBlossom/BloomingBlossomScript"] = pathTrail("Green", "Purple")

	local function breathe(ctx)
		local tr = ctx.parent
		local t = 0
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			t = t + dt
			tr.Lifetime = (math.sin(t * math.pi) + 1) / 2 / 2 + 1
		end))
	end
	PORTS["OoeyGooey/Origin"] = breathe
	PORTS["OoeyGooey/AnimateOoeyGooey"] = breathe

	PORTS["Afterimage/Afterimage"] = function(ctx)
		local char = ctx.char
		local camera = workspace.CurrentCamera
		local GHOSTS, LIFE, START = 6, 0.9, 0.45

		local holder = ctx.made(Instance.new("Folder"))
		holder.Name = ctx.player.Name .. "_Afterimages"
		holder.Parent = workspace

		local pool = {}

		local function bodyParts(model)
			local out = {}
			for _, d in ipairs(model:GetDescendants()) do
				if d:IsA("BasePart") then out[#out + 1] = d end
			end
			return out
		end

		local function ghost()
			local was = char.Archivable
			char.Archivable = true
			local ok, copy = pcall(function() return char:Clone() end)
			char.Archivable = was
			if not (ok and copy) then return nil end

			for _, d in ipairs(copy:GetDescendants()) do
				pcall(function()
					if d:IsA("LuaSourceContainer") or d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam")
						or d:IsA("Light") or d:IsA("Sound") or d:IsA("BillboardGui") or d:IsA("Highlight")
						or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles") then
						d:Destroy()
					elseif d:IsA("BasePart") then
						d.Anchored, d.CanCollide, d.CanQuery, d.CanTouch, d.Massless = true, false, false, false, true
						d.Transparency = 1
					elseif d:IsA("Decal") or d:IsA("Texture") then
						d.Transparency = 1
					end
				end)
			end

			local humanoid = copy:FindFirstChildOfClass("Humanoid")
			if humanoid then
				pcall(function()
					humanoid.EvaluateStateMachine = false
					humanoid.PlatformStand = true
					humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
					humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
				end)
				local animator = humanoid:FindFirstChildOfClass("Animator")
				if animator then animator:Destroy() end
			end

			copy.Name = "Afterimage"
			copy.Parent = holder

			return { model = copy, parts = bodyParts(copy), skins = {}, age = LIFE }
		end

		local function faces(model)
			local out = {}
			for _, d in ipairs(model:GetDescendants()) do
				if d:IsA("Decal") or d:IsA("Texture") then out[#out + 1] = d end
			end
			return out
		end

		local function paint(entry, alpha)
			for _, part in ipairs(entry.parts) do
				if part.Parent then part.Transparency = alpha end
			end
			for _, face in ipairs(entry.skins) do
				if face.Parent then face.Transparency = alpha end
			end
		end

		local beat = 0
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			beat += dt
			if beat < 1 / 30 then return end
			dt, beat = beat, 0

			for _, entry in ipairs(pool) do
				if entry.age < LIFE then
					entry.age += dt
					paint(entry, math.min(START + (entry.age / LIFE) * (1 - START), 1))
				end
			end
		end))

		local source = bodyParts(char)

		while ctx.alive() and char.Parent do
			task.wait(1 / 12)

			local root = char:FindFirstChild("HumanoidRootPart")
			local far = root and (camera.CFrame.Position - root.Position).Magnitude >= 128
			if root and not far and root.AssemblyLinearVelocity.Magnitude >= 2 then

				local live = bodyParts(char)
				if #live ~= #source then
					source = live
					for _, entry in ipairs(pool) do entry.model:Destroy() end
					table.clear(pool)
				end

				local pick
				for _, entry in ipairs(pool) do
					if not entry.model.Parent then continue end
					if not pick or entry.age > pick.age then pick = entry end
				end

				if (not pick or pick.age < LIFE) and #pool < GHOSTS then
					local made = ghost()
					if made then
						made.skins = faces(made.model)
						pool[#pool + 1] = made
						pick = made
					end
				end

				if pick and #pick.parts == #source then
					local frames = table.create(#source)
					for index, part in ipairs(source) do frames[index] = part.CFrame end
					pcall(function()
						workspace:BulkMoveTo(pick.parts, frames, Enum.BulkMoveMode.FireCFrameChanged)
					end)
					pick.age = 0
					paint(pick, START)
				end
			end
		end

		for _, entry in ipairs(pool) do pcall(function() entry.model:Destroy() end) end
	end

	local function playOrSpin(ctx, animName, spinRate, randomStart)
		local model = ctx.parent
		local controller = model:FindFirstChildOfClass("AnimationController")
		local id = ctx.anims[animName]
		if controller and id then
			local animator = controller:FindFirstChildOfClass("Animator") or controller
			local anim = Instance.new("Animation")
			anim.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(anim) end)
			if ok and track then
				track:Play(0)
				local t0 = os.clock()
				repeat task.wait(0.1) until track.Length > 0 or os.clock() - t0 > 3 or not ctx.alive()
				if track.Length > 0 then
					if randomStart then track.TimePosition = Random.new(tick()):NextNumber(0, track.Length) end
					ctx.undo(function() pcall(function() track:Stop(0) end) end)
					return
				end
				pcall(function() track:Stop(0) end)
			end
		end
		if not spinRate then return end
		local joints = {}
		for _, j in ipairs(model:GetDescendants()) do
			if j:IsA("Motor6D") then joints[#joints + 1] = { j, j.C0 } end
		end
		local t = randomStart and math.random() * 10 or 0
		ctx.conn(RunService.RenderStepped:Connect(function(dt)
			t = t + dt
			for _, v in ipairs(joints) do v[1].C0 = v[2] * CFrame.Angles(0, t * spinRate, 0) end
		end))
	end

	PORTS["spins/Script"] = function(ctx) playOrSpin(ctx, "Animation", 1.4, true) end

	PORTS["Model/Script"] = function(ctx)
		task.wait()
		playOrSpin(ctx, "Voidstar", 0.8, false)
	end
	PORTS["NeonSign/LocalScript"] = function(ctx) playOrSpin(ctx, "Animation", nil, false) end

	local RAINBOW = {
		Color3.fromRGB(255, 52, 52), Color3.fromRGB(216, 140, 63), Color3.fromRGB(239, 235, 95),
		Color3.fromRGB(137, 216, 102), Color3.fromRGB(105, 177, 216), Color3.fromRGB(112, 98, 216),
	}
	local function cycleOutline(ctx, hl)
		local info = TweenInfo.new(1, Enum.EasingStyle.Linear, Enum.EasingDirection.Out)
		while ctx.alive() and hl.Parent and hl.Parent.Parent do
			for _, c in ipairs(RAINBOW) do
				if not ctx.alive() then return end
				TweenService:Create(hl, info, { OutlineColor = c }):Play()
				task.wait(0.5)
			end
		end
	end

	PORTS["Glow/LocalScript"] = function(ctx)
		task.wait(1)
		local hl = ctx.parent
		hl.Adornee = ctx.char
		cycleOutline(ctx, hl)
	end

	PORTS["GlowSolid/LocalScript"] = function(ctx)
		task.wait(1)
		ctx.parent.Adornee = ctx.char
	end

	PORTS["Grunt/LocalScript"] = function(ctx) cycleOutline(ctx, ctx.parent) end

	local live, wanted, busy = {}, {}, {};
	local current = nil;

	local function unequip(id, store)
		store = store or live;
		local l = store[id];
		if not l then return end;
		store[id] = nil;
		l.alive = false;
		for _, c in ipairs(l.conns) do pcall(function() c:Disconnect() end) end;
		for i = #l.undo, 1, -1 do pcall(l.undo[i]) end;
		for _, inst in ipairs(l.made) do pcall(function() inst:Destroy() end) end;
	end;

	local function resolveAt(l, at)
		if at == "" then return l.char end;
		local node = nil;
		for seg in string.gmatch(at, "[^%.]+") do
			if node == nil then node = l.roots[seg] else node = node:FindFirstChild(seg) end;
			if not node then return nil end;
		end;
		return node;
	end;

	local function runScripts(item, l, owner)
		for _, s in ipairs(l.scripts or {}) do
			local holder = s.at:match("([^%.]+)$") or "";
			local port = PORTS[item.key .. "/" .. s.n] or PORTS[holder .. "/" .. s.n];
			local parent = resolveAt(l, s.at);
			if port and parent then
				local ctx = {
					char = l.char, player = owner or LocalPlayer, parent = parent, live = l, anims = s.anims or {},
					limb = function(n) return (limb(l.char, n)) end,
					conn = function(c) l.conns[#l.conns + 1] = c; return c end,
					undo = function(fn) l.undo[#l.undo + 1] = fn end,
					alive = function() return l.alive and ALIVE end,
					made = function(inst) l.made[#l.made + 1] = inst; return inst end,
				};
				task.spawn(function()
					local ok, err = pcall(port, ctx);
					if not ok then recordError("game fx " .. item.key .. "/" .. s.n .. ": " .. tostring(err)) end;
				end);
			end;
		end;
	end;

	local function equip(id, item, char, group, store, owner)
		local trees, scripts = item.trees, item.scripts;
		if item.mode == "rig" then
			local r15 = char:FindFirstChild("UpperTorso") ~= nil;
			local v = r15 and (item.r15 or item.r6) or (item.r6 or item.r15);
			trees, scripts = {}, v and v.scripts or {};
			for i, node in ipairs(v and v.limbs or {}) do trees[i] = node end;
			if item.aura then trees[#trees + 1] = item.aura end;
		end;
		local ctx = { map = {}, refs = {}, char = char, limbKids = {} };
		local roots = {};
		for _, node in ipairs(trees) do
			local r = build(node, ctx);
			if r then roots[#roots + 1] = r end;
		end;

		local stale = store and not char.Parent or (not store and (char ~= wearer() or wanted[id] ~= group));
		if stale or not ALIVE then
			for _, r in ipairs(roots) do pcall(function() r:Destroy() end) end;
			for _, k in ipairs(ctx.limbKids) do pcall(function() k[1]:Destroy() end) end;
			return;
		end;
		local l = { item = item, char = char, made = {}, conns = {}, undo = {}, roots = {}, worn = {}, transforms = {}, alive = true, scripts = scripts, group = group };
		local prefix = item.kind == "Trail" and "Trail_" or "Aura_";
		local placed, worn = {}, {};

		for _, root in ipairs(roots) do
			if item.mode == "parts" and root:IsA("BasePart") then
				local templateName = root.Name;
				local body, off = limb(char, templateName);
				if not body then body, off = limb(char, "HumanoidRootPart") end;
				if body then
					local shift = body.CFrame * off * root.CFrame:Inverse();
					for _, p in ipairs(partsUnder(root)) do p.CFrame = shift * p.CFrame end;

					root.Transparency = 1;
					root.Name = prefix .. templateName;
					l.roots[templateName] = root;
					placed[#placed + 1] = { root, body, off };
				else
					root:Destroy();
				end;
			elseif item.mode == "rig" and root:IsA("BasePart") then

				local mount = limb(char, "HumanoidRootPart");
				if mount then
					root.Name = "Aura";
					local anchor = Instance.new("Attachment");
					anchor.Name = "AuraMount";
					anchor.Parent = root;
					local first = mount:FindFirstChildOfClass("Attachment");
					local c0 = first and first.CFrame or CFrame.new();
					for _, p in ipairs(partsUnder(root)) do
						p.CFrame = mount.CFrame * c0 * root.CFrame:Inverse() * p.CFrame;
					end;
					root.Transparency = 1;
					placed[#placed + 1] = { root, mount, c0, true };
				else
					root:Destroy();
				end;
			elseif item.mode == "attach" and root:IsA("Attachment") then
				local body, off = limb(char, "Torso");
				if body then
					root.CFrame = off * root.CFrame;
					root.Name = item.kind == "Trail" and "Trail" or "AuraAttachment";
					placed[#placed + 1] = { root, body };
				else
					root:Destroy();
				end;
			elseif item.mode == "trail" and root:IsA("Trail") then
				local body, off = limb(char, "Torso");
				if body then
					local w = tonumber(item.width) or 1;
					local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment");
					a0.Name, a1.Name = "LeftTrail", "RightTrail";
					a0.CFrame, a1.CFrame = off * CFrame.new(-w, 0, 0), off * CFrame.new(w, 0, 0);
					a0.Parent, a1.Parent = body, body;
					root.Attachment0, root.Attachment1 = a0, a1;
					l.made[#l.made + 1] = a0;
					l.made[#l.made + 1] = a1;
					placed[#placed + 1] = { root, body };
				else
					root:Destroy();
				end;
			else
				root:Destroy();
			end;
		end;

		for _, k in ipairs(ctx.limbKids) do
			local child, target, cf = k[1], k[2], k[3];
			if cf then
				local shift = target.CFrame * cf:Inverse();
				for _, p in ipairs(partsUnder(child)) do p.CFrame = shift * p.CFrame end;
			end;
			if child:IsA("Attachment") then
				local same = target:FindFirstChild(child.Name);
				if same and same:IsA("Attachment") then child.CFrame = same.CFrame end;
			end;
			l.roots[target.Name] = target;
		end;

		for _, r in ipairs(ctx.refs) do
			local target = ctx.map[r[3]];
			if target then pcall(function() r[1][r[2]] = target end) end;
		end;

		for _, k in ipairs(ctx.limbKids) do
			k[1].Parent = k[2];
			l.made[#l.made + 1] = k[1];
			worn[#worn + 1] = k[1];
		end;

		for _, p in ipairs(placed) do
			local root, body, off, aura = p[1], p[2], p[3], p[4];
			root.Parent = body;
			if off then

				local weld = Instance.new("Weld");
				weld.Name = "Weld";
				weld.Part0, weld.Part1 = body, root;
				weld.C0, weld.C1 = off, CFrame.new();
				weld.Parent = root;
			end;
			l.made[#l.made + 1] = root;
			worn[#worn + 1] = root;
		end;

		l.worn = worn;
		captureCosmeticTransforms(l);
		remember(l, worn);
		(store or live)[id] = l;
		applyTune(l);
		runScripts(item, l, owner);
	end;

	local refreshHooks = {};
	local function changed()
		for _, fn in ipairs(refreshHooks) do pcall(fn) end;
	end;

	local function apply(id)
		local entry, char, group = FX.ById[id], current, wanted[id];
		if not (entry and char and group) or live[id] or busy[id] then return end;
		busy[id] = true;
		changed();
		task.spawn(function()
			local ok, err = pcall(function()
				local data = loadGame(entry.g);
				local item = data and data[id];
				if item and ALIVE and wanted[id] == group and current == char then equip(id, item, char, group) end;
			end);
			if not ok then recordError("game fx " .. id .. ": " .. tostring(err)) end;
			busy[id] = nil;
			changed();
		end);
	end;

	function FX.Set(id, group)
		if not FX.ById[id] then return end;
		if wanted[id] == group then return end;
		unequip(id);
		wanted[id] = group;
		if group then apply(id) end;
	end;

	function FX.SetGroup(group, ids)
		local keep = {};
		for _, id in ipairs(ids or {}) do if FX.ById[id] then keep[id] = true end end;
		for id, g in pairs(wanted) do
			if g == group and not keep[id] then FX.Set(id, nil) end;
		end;
		for id in pairs(keep) do FX.Set(id, group) end;
	end;

	local guests = {};

	local function bodyOf(player)
		local char = player.Character;
		local rigs = workspace:FindFirstChild("Rigs");
		local rig = rigs and rigs:FindFirstChild(player.Name);

		if char and char.Parent and shown(char) and drawn(char) then return char end;
		if rig and rig:IsA("Model") and shown(rig) then return rig end;
		if char and char.Parent and shown(char) then return char end;

		return nil;
	end;

	local function guestStrip(g)
		for id in pairs(g.worn) do unequip(id, g.worn) end;
	end;

	function FX.Undress(player)
		local g = guests[player];
		if not g then return end;
		guestStrip(g);
		guests[player] = nil;
	end;

	function FX.Guests() return guests end;

	function FX.Dress(player, list)
		if not player or player == LocalPlayer then return end;

		local g = guests[player];

		if not g then
			g = { worn = {}, busy = {}, want = {} };
			guests[player] = g;
		end;

		local want = {};

		for _, entry in ipairs(list or {}) do
			local id = (type(entry) == "table") and entry.id or entry;

			if FX.ById[id] then want[id] = (type(entry) == "table" and entry.group) or "aura" end;
		end;

		g.want = want;
	end;

	local function serveGuest(player, g)
		local char = bodyOf(player);

		if not char then
			if next(g.worn) then guestStrip(g) end;
			g.char = nil;
			return;
		end;

		if g.char ~= char then
			guestStrip(g);
			g.char = char;
		end;

		for id in pairs(g.worn) do
			if not g.want[id] then unequip(id, g.worn) end;
		end;

		for id, group in pairs(g.want) do
			if not g.worn[id] and not g.busy[id] then
				g.busy[id] = true;

				task.spawn(function()
					local ok, err = pcall(function()
						local entry = FX.ById[id];
						local data = entry and loadGame(entry.g);
						local item = data and data[id];

						if item and ALIVE and g.want[id] and g.char == char and char.Parent then
							equip(id, item, char, group, g.worn, player);
						end;
					end);

					if not ok then recordError("share " .. tostring(id) .. ": " .. tostring(err)) end;

					g.busy[id] = nil;
				end);
			end;
		end;
	end;

	task.spawn(function()
		while ALIVE do
			task.wait(0.5);

			for player, g in pairs(guests) do
				if not player.Parent then FX.Undress(player) else pcall(serveGuest, player, g) end;
			end;
		end;
	end);

	function FX.WornList()
		local out = {};

		for id, group in pairs(wanted) do
			if group then out[#out + 1] = { id = id, group = group } end;
		end;

		return out;
	end;

	function FX.Tune(group, t)
		tuning[group] = t;
		for _, l in pairs(live) do
			if l.group == group then applyTune(l) end;
		end;
	end;

	local thumbHooks, thumbState = {}, "idle";
	local function thumbKey(id)
		return (tostring(id):gsub("[^%w_%.%-]", "_"));
	end;
	function FX.OnThumbs(fn) thumbHooks[#thumbHooks + 1] = fn end;

	function FX.Art(key, fallback)
		local spot = FX.ThumbMap and FX.ThumbMap[thumbKey(key)];
		local sheet = spot and FX.ThumbSheets[spot[1]];
		if not sheet then return fallback end;
		local cell = FX.ThumbCell;
		return sheet, Vector2.new(spot[2] * cell, spot[3] * cell), Vector2.new(cell, cell);
	end;

	function FX.Row(entry)
		local shop = entry.image ~= "" and entry.image ~= "rbxassetid://0" and entry.image or nil;
		local image, rect, size = shop, nil, nil;
		if not (entry.g == "nullscape" and shop) then image, rect, size = FX.Art(entry.id, shop) end;
		return { name = entry.id, label = entry.label, image = image, rect = rect, rectsize = size };
	end;

	function FX.LoadThumbs()
		if thumbState ~= "idle" then return end;
		thumbState = "loading";
		task.spawn(function()
			local raw = Remote.body("fxatlas/index.json");
			local ok, index = pcall(function() return game:GetService("HttpService"):JSONDecode(raw) end);
			if not (ok and type(index) == "table" and type(index.map) == "table" and type(index.sheets) == "table") then
				thumbState = "idle";
				return;
			end;
			local sheets = {};
			for n, rel in ipairs(index.sheets) do
				if not ALIVE then return end;
				sheets[n] = Remote.asset(rel);
			end;
			FX.ThumbMap, FX.ThumbSheets, FX.ThumbCell = index.map, sheets, tonumber(index.cell) or 128;
			thumbState = "ready";
			for _, fn in ipairs(thumbHooks) do pcall(fn) end;
		end);
	end;

	task.delay(12, function() if ALIVE then FX.LoadThumbs() end end);

	function FX.Busy(id) return busy[id] == true end;
	function FX.Worn(id) return live[id] ~= nil end;
	function FX.OnChange(fn) refreshHooks[#refreshHooks + 1] = fn end;

	task.spawn(function()
		while ALIVE do
			local now = wearer();
			if now ~= current then
				for id in pairs(live) do unequip(id) end;
				current = nil;
				if now then
					task.wait(0.5);
					if ALIVE and wearer() == now then
						current = now;
						for id in pairs(wanted) do apply(id) end;
					end;
				end;
			else
				for id, l in pairs(live) do
					if not l.char.Parent then unequip(id) end;
				end;
			end;
			task.wait(0.5);
		end;
	end);

	ESP.ClearGameFX = onUnload("gamefx", function()
		for player in pairs(guests) do pcall(FX.Undress, player) end;
		table.clear(wanted);
		for id in pairs(live) do unequip(id) end;
		for _, m in pairs(meshCache) do pcall(function() m:Destroy() end) end;
		table.clear(meshCache);
	end);
end);

guard("aura", function()

	local ORDER = {
		"Angelic", "Ambient", "Nimb", "Tornado", "Comet",
		"Angel", "Starlight", "Heavenly", "Ribbon", "Sakura", "Wind", "Flow", "Star",
	};

	local CATALOGUE = {
		Angel = "97658130917593",
		Starlight = "134645216613107",
		Heavenly = "139300897520961",
		Ribbon = "132069507632161",
		Sakura = "81755778619404",
		Wind = "80694081850877",
		Flow = "119913533725648",
		Star = "73754563740680",
	};

	local GROUPS = {
		{ "Head" },
		{ "Torso", "UpperTorso", "LowerTorso", "HumanoidRootPart" },
		{ "Left Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand" },
		{ "Right Arm", "RightUpperArm", "RightLowerArm", "RightHand" },
		{ "Left Leg", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot" },
		{ "Right Leg", "RightUpperLeg", "RightLowerLeg", "RightFoot" },
	};

	local GROUP_OF = {};

	for _, names in ipairs(GROUPS) do
		for _, name in ipairs(names) do GROUP_OF[name] = names end;
	end;

	local A = {
		On = false,
		Color = Color3.fromRGB(133, 220, 255),
		Types = {},
		Type = "Angelic",
		Target = "Self",
		Glow = 2,
		Rate = 1,
		Size = 1,
		Tint = true,
		Speed = 1, Radius = 0.55, TrailLength = 100, TrailStep = 1.5, BloomSize = 150,
		LoadErrors = {}, ReadyTypes = {},
	};

	ESP.Aura = A;

	local function newBank(color)
		return { attachments = {}, borrowed = {}, particles = {}, accents = {}, color = color or A.Color };
	end;

	local mine = newBank();
	local sink = mine;
	local charConnection = nil;
	local auraGeneration = 0;

	local function clearBank(bank)
		for i = 1, #bank.attachments do
			if bank.attachments[i] and bank.attachments[i].Parent then
				bank.attachments[i]:Destroy();
			end;
		end;

		for i = 1, #bank.borrowed do
			if bank.borrowed[i] and bank.borrowed[i].Parent then
				pcall(function() bank.borrowed[i]:Destroy() end);
			end;
		end;

		bank.attachments, bank.borrowed, bank.particles, bank.accents = {}, {}, {}, {};
	end;

	local function clearAll()
		clearBank(mine);
		table.clear(A.ReadyTypes);
	end;

	local function keep(emitter, attachment)
		emitter.Parent = attachment;
		Render.FxDepth(emitter, false);

		sink.particles[#sink.particles + 1] = {
			emitter = emitter,
			rate = emitter.Rate,
			bright = emitter.Brightness,
			size = emitter.Size,
			color = emitter.Color, speed = emitter.Speed, rotation = emitter.RotSpeed,
			life = emitter.Lifetime, emission = emitter.LightEmission,
		};

		return emitter;
	end;

	local function scaleSequence(sequence, factor)
		if factor == 1 then return sequence end;

		local points = {};

		for index, key in ipairs(sequence.Keypoints) do
			points[index] = NumberSequenceKeypoint.new(key.Time, key.Value * factor, key.Envelope * factor);
		end;

		return NumberSequence.new(points);
	end;

	local guests = {};

	local function tuneBank(bank)
		local colour = bank.color;

		for _, record in ipairs(bank.particles) do
			local emitter = record.emitter;

			if emitter.Parent then
				Render.FxDepth(emitter, false);
				emitter.Color = A.Tint and ColorSequence.new(colour) or record.color;
				emitter.Rate = record.rate * A.Rate;
				emitter.Brightness = record.bright * A.Glow * 0.5;
				emitter.Size = scaleSequence(record.size, A.Size);
				local speed = math.clamp(A.Speed, 0.05, 5);
				emitter.Speed = NumberRange.new(record.speed.Min * speed, record.speed.Max * speed);
				emitter.RotSpeed = NumberRange.new(record.rotation.Min * speed, record.rotation.Max * speed);
				emitter.Lifetime = NumberRange.new(math.max(0.05, record.life.Min / speed), math.max(0.06, record.life.Max / speed));
				emitter.LightEmission = math.clamp(record.emission + (A.Glow * 0.5 - 1) * 0.5, 0, 1);
			end;
		end;

		for _, record in ipairs(bank.accents) do
			local item = record.item;
			if item.Parent then
				Render.FxDepth(item, false);
				pcall(function()
					if item:IsA("PointLight") or item:IsA("SpotLight") or item:IsA("SurfaceLight") then
						item.Color = A.Tint and colour or record.color;
						item.Brightness = record.brightness * A.Glow * 0.5;
					elseif item:IsA("Beam") or item:IsA("Trail") then
						item.Color = A.Tint and ColorSequence.new(colour) or record.color;
					end;
				end);
			end;
		end;
	end;

	local function tune()
		mine.color = A.Color;
		tuneBank(mine);

		for _, bank in pairs(guests) do tuneBank(bank) end;

		if ESP.GameFX then
			ESP.GameFX.Tune("aura", {
				glow = A.Glow * 0.5, rate = A.Rate, size = A.Size, speed = A.Speed,
			});
		end;
	end;

	local function part(character, ...)
		for _, name in ipairs({ ... }) do
			local found = character:FindFirstChild(name);

			if found then return found end;
		end;

		return nil;
	end;

	local function anchor(host, cframe)
		local attachment = Instance.new("Attachment");

		attachment.CFrame = cframe;
		attachment.Parent = host;

		sink.attachments[#sink.attachments + 1] = attachment;

		return attachment;
	end;

	local function createAngelic(character)
		local torso = part(character, "Torso", "UpperTorso");

		if not torso then return end;

		local left = anchor(torso, CFrame.new(-1.012, 0.5, 0.852, 0.966, 0, 0.259, 0, 1, 0, -0.259, 0, 0.966));
		local wingL = Instance.new("ParticleEmitter");
		wingL.Lifetime = NumberRange.new(1, 1);
		wingL.LockedToPart = true;
		wingL.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.944),
			NumberSequenceKeypoint.new(0.2, 0),
			NumberSequenceKeypoint.new(0.8, 0),
			NumberSequenceKeypoint.new(1, 1),
		});
		wingL.LightEmission = 1;
		wingL.Color = ColorSequence.new(A.Color);
		wingL.Speed = NumberRange.new(0.05, 0.05);
		wingL.Size = NumberSequence.new(2.75, 3.5);
		wingL.Rate = 4;
		wingL.Texture = "rbxassetid://13267054240";
		wingL.EmissionDirection = Enum.NormalId.Back;
		wingL.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
		wingL.Rotation = NumberRange.new(-15, -15);
		keep(wingL, left);

		local right = anchor(torso, CFrame.new(1.167, 0.5, 0.852, 0.966, 0, -0.259, 0, 1, 0, 0.259, 0, 0.966));
		local wingR = wingL:Clone();
		wingR.EmissionDirection = Enum.NormalId.Front;
		keep(wingR, right);

		local core = anchor(torso, CFrame.new(0, 0.3, 0));
		local burst = Instance.new("ParticleEmitter");
		burst.Lifetime = NumberRange.new(2, 2);
		burst.FlipbookLayout = Enum.ParticleFlipbookLayout.Grid4x4;
		burst.SpreadAngle = Vector2.new(180, 180);
		burst.LockedToPart = true;
		burst.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.5, 0.3),
			NumberSequenceKeypoint.new(1, 1),
		});
		burst.LightEmission = 1;
		burst.Color = ColorSequence.new(A.Color);
		burst.Speed = NumberRange.new(0.5, 0.5);
		burst.Brightness = 2;
		burst.Size = NumberSequence.new(3, 4);
		burst.Rate = 5;
		burst.Texture = "rbxassetid://11402221943";
		burst.FlipbookMode = Enum.ParticleFlipbookMode.OneShot;
		burst.Rotation = NumberRange.new(0, 360);
		keep(burst, core);
	end;

	local function createAmbient(character)
		local hrp = part(character, "HumanoidRootPart");

		if not hrp then return end;

		local base = anchor(hrp, CFrame.new(0, -2.75, 0));

		local grow = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(0.3, 1),
			NumberSequenceKeypoint.new(0.6, 2.5),
			NumberSequenceKeypoint.new(0.8, 4),
			NumberSequenceKeypoint.new(1, 6),
		});

		local crescent = Instance.new("ParticleEmitter");
		crescent.Lifetime = NumberRange.new(2, 2);
		crescent.SpreadAngle = Vector2.new(0.001, 0.001);
		crescent.LockedToPart = true;
		crescent.Transparency = NumberSequence.new(0, 1);
		crescent.LightEmission = 1;
		crescent.Color = ColorSequence.new(A.Color);
		crescent.Squash = NumberSequence.new(0);
		crescent.Speed = NumberRange.new(0.001, 0.001);
		crescent.Brightness = 2;
		crescent.Size = grow;
		crescent.RotSpeed = NumberRange.new(-600, 600);
		crescent.Texture = "rbxassetid://12713358087";
		crescent.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
		crescent.Rotation = NumberRange.new(0, 360);
		keep(crescent, base);

		local ring = Instance.new("ParticleEmitter");
		ring.Lifetime = NumberRange.new(2, 2);
		ring.SpreadAngle = Vector2.new(0.001, 0.001);
		ring.LockedToPart = true;
		ring.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(0.6, 0.2),
			NumberSequenceKeypoint.new(1, 1),
		});
		ring.LightEmission = 1;
		ring.Color = ColorSequence.new(A.Color);
		ring.Squash = NumberSequence.new(0, 2);
		ring.Speed = NumberRange.new(0.001, 0.001);
		ring.Brightness = 2;
		ring.Size = grow;
		ring.RotSpeed = NumberRange.new(-30, 30);
		ring.Texture = "rbxassetid://7216849325";
		ring.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
		ring.Rotation = NumberRange.new(0, 360);
		keep(ring, base);

		local wide = Instance.new("ParticleEmitter");
		wide.Lifetime = NumberRange.new(2, 2);
		wide.SpreadAngle = Vector2.new(0.001, 0.001);
		wide.LockedToPart = true;
		wide.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.2, 0.3),
			NumberSequenceKeypoint.new(1, 1),
		});
		wide.LightEmission = 1;
		wide.Color = ColorSequence.new(A.Color);
		wide.Squash = NumberSequence.new(0);
		wide.Speed = NumberRange.new(0.001, 0.001);
		wide.Brightness = 2;
		wide.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(0.3, 2),
			NumberSequenceKeypoint.new(0.6, 5),
			NumberSequenceKeypoint.new(0.8, 8),
			NumberSequenceKeypoint.new(1, 12),
		});
		wide.RotSpeed = NumberRange.new(-40, 40);
		wide.Texture = "rbxassetid://7216855136";
		wide.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
		wide.Rotation = NumberRange.new(0, 360);
		keep(wide, base);
	end;

	local function createNimb(character)
		local head = part(character, "Head");

		if not head then return end;

		local halo = anchor(head, CFrame.new(-0.25, 0.933, 0.259, 0.469, -0.25, -0.847, -0.117, 0.933, -0.34, 0.875, 0.259, 0.408));

		for index = 1, 2 do
			local emitter = Instance.new("ParticleEmitter");
			emitter.Lifetime = NumberRange.new(1, 1);
			emitter.SpreadAngle = Vector2.new(5, 5);
			emitter.LockedToPart = true;
			emitter.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(0.2, 0),
				NumberSequenceKeypoint.new(0.8, 0),
				NumberSequenceKeypoint.new(1, 1),
			});
			emitter.LightEmission = 1;
			emitter.Color = ColorSequence.new(A.Color);
			emitter.Speed = NumberRange.new(0.001, 0.001);
			emitter.Brightness = 2;
			emitter.Size = (index == 1) and NumberSequence.new(2.5, 3) or NumberSequence.new(2, 3);
			emitter.RotSpeed = NumberRange.new(-400, 400);
			emitter.Rate = 7;
			emitter.Texture = "rbxassetid://8819682608";
			emitter.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
			emitter.Rotation = NumberRange.new(0, 360);
			keep(emitter, halo);
		end;
	end;

	local function createTornado(character)
		local hrp = part(character, "HumanoidRootPart");

		if not hrp then return end;

		local base = anchor(hrp, CFrame.new(0, -3, 0));

		local funnel = Instance.new("ParticleEmitter");
		funnel.LightInfluence = 1;
		funnel.LockedToPart = true;
		funnel.LightEmission = 1;
		funnel.Color = ColorSequence.new(A.Color);
		funnel.Speed = NumberRange.new(0.01, 0.01);
		funnel.Size = NumberSequence.new(6, 10);
		funnel.RotSpeed = NumberRange.new(360, 360);
		funnel.Rate = 1;
		funnel.Texture = "rbxassetid://8553497052";
		funnel.Orientation = Enum.ParticleOrientation.VelocityPerpendicular;
		keep(funnel, base);
	end;

	local loaded = {};
	local loading = {};

	local function fetchAura(name)
		if loaded[name] ~= nil then return loaded[name] or nil end;
		if loading[name] then
			local deadline = os.clock() + 13;
			repeat task.wait(0.03) until not loading[name] or not ALIVE or os.clock() >= deadline;
			return loaded[name];
		end;

		local id = CATALOGUE[name];

		if not id then return nil end;

		loading[name] = true;
		local ok, objects = Remote.objects(function() return game:GetObjects("rbxassetid://" .. id) end);
		loading[name] = nil;
		local source = (ok and type(objects) == "table") and objects[1] or nil;

		if type(objects) == "table" then for index = 2, #objects do pcall(function() objects[index]:Destroy() end) end end;
		if not ALIVE then if source then source:Destroy() end; return nil end;
		loaded[name] = source;
		if source then A.LoadErrors[name] = nil else A.LoadErrors[name] = "Asset unavailable: " .. id end;

		return source;
	end;

	local function slotFor(character, name)
		local direct = character:FindFirstChild(name, true);

		if direct and direct:IsA("BasePart") then return direct end;

		for _, alias in ipairs(GROUP_OF[name] or {}) do
			local found = character:FindFirstChild(alias, true);

			if found and found:IsA("BasePart") then return found end;
		end;

		return nil;
	end;

	local function createCatalogue(name)
		return function(character, generation, bank)

			bank = bank or sink;
			sink = mine;

			local source = fetchAura(name);
			local ours = bank == mine;

			if not source or not ALIVE or not character.Parent then return end;
			if ours and (not A.On or generation ~= auraGeneration or LocalPlayer.Character ~= character) then return end;

			local held = sink;
			sink = bank;

			local clone = source:Clone();
			for _, item in ipairs(clone:GetDescendants()) do
				if item:IsA("LuaSourceContainer") then item:Destroy() end;
			end;

			for _, group in ipairs(clone:GetChildren()) do
				local target = slotFor(character, group.Name) or part(character, "UpperTorso", "Torso", "HumanoidRootPart");

				if target then
					for _, child in ipairs(group:GetChildren()) do
						child.Parent = target;

						sink.borrowed[#sink.borrowed + 1] = child;

						local nodes = child:GetDescendants(); nodes[#nodes + 1] = child;
						for _, item in ipairs(nodes) do
							if item:IsA("ParticleEmitter") then keep(item, item.Parent);
							elseif item:IsA("Light") or item:IsA("Beam") or item:IsA("Trail") then
								sink.accents[#sink.accents + 1] = { item = item, color = item.Color,
									brightness = item:IsA("Light") and item.Brightness or 1 };
							end;
						end;
					end;
				end;
			end;

			clone:Destroy();
			sink = held;
		end;
	end;

	local cometHost = Render.gui("comet aura", -7);
	local cometSprites, cometTexture = {}, nil;
	local cometClock, cometFade = 0, 0;
	A.CometSprites = cometSprites;
	local function hideComet()
		for _, sprite in ipairs(cometSprites) do sprite.Visible = false end;
	end;
	NeverLose:AddSignal(RunService.RenderStepped:Connect(function(dt)
		if not ALIVE then return end;
		if not (A.On and A.Types.Comet) and cometFade <= 0 then return end;
		local character = LocalPlayer.Character;
		local root = character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart"));
		local camera = Render.camera();
		local active = A.On and A.Types.Comet and root and root:IsA("BasePart") and camera;
		cometFade = math.clamp(cometFade + (active and dt or -dt) / 0.35, 0, 1);
		if not root or not camera or cometFade <= 0 then hideComet(); return end;
		cometClock += dt;
		if cometClock < 1 / 30 then return end;
		cometClock %= 1 / 30;
		if not ESP.Visibility.Part(camera, root, character) then hideComet(); return end;
		if not cometTexture then
			cometTexture = Remote.id(Remote.file("particles/comet_bloom.png"));
			if not cometTexture then hideComet(); return end;
		end;
		local count = math.clamp(math.floor(A.TrailLength), 20, 300);
		local distance = math.max(1.5, (camera.CFrame.Position - root.Position).Magnitude);
		local time = DateTime.now().UnixTimestampMillis;
		local baseSize = math.clamp(A.BloomSize * A.Size * camera.ViewportSize.Y / 720 / distance, 1, 160);
		local index = 0;
		for i = 0, count - 1 do
			local angle = 0.1 * (time - i * 1.5 * 300 / count * A.TrailStep) / (30 / A.Speed);
			local s, c = math.sin(angle) * A.Radius, math.cos(angle) * A.Radius;
			local progress = i / count;
			local diameter = math.max(1, baseSize * (1 - progress) ^ 1.1);
			local alpha = math.clamp(cometFade * (1 - progress * progress) * 0.4 * A.Glow * 0.5, 0, 0.95);
			for _, offset in ipairs({ Vector3.new(s, c, -c), Vector3.new(-s, s, -c), Vector3.new(-s, -s, c) }) do
				index += 1;
				local sprite = cometSprites[index];
				if not sprite then
					sprite = Instance.new("ImageLabel");
					sprite.Name = "VisualsCometBloom";
					sprite.BackgroundTransparency, sprite.BorderSizePixel = 1, 0;
					sprite.AnchorPoint, sprite.Image = Vector2.new(0.5, 0.5), cometTexture;
					sprite.Parent = cometHost;
					cometSprites[index] = sprite;
				end;
				local at, visible = camera:WorldToViewportPoint(root.Position + offset);
				sprite.Visible = visible and at.Z > 0 and alpha > 0.005;
				if sprite.Visible then
					sprite.Position, sprite.Size = UDim2.fromOffset(at.X, at.Y), UDim2.fromOffset(diameter, diameter);
					sprite.ImageColor3, sprite.ImageTransparency = A.Color, 1 - alpha;
					sprite.Rotation = (time / 5 + i * 5) % 180;
				end;
			end;
		end;
		for i = #cometSprites, index + 1, -1 do cometSprites[i]:Destroy(); cometSprites[i] = nil end;
	end));
	local BUILDERS = {
		Angelic = createAngelic,
		Ambient = createAmbient,
		Nimb = createNimb,
		Tornado = createTornado,

		Comet = function() end,
	};

	for name in pairs(CATALOGUE) do BUILDERS[name] = createCatalogue(name) end;

	local function refreshAuras()
		auraGeneration += 1;
		local generation = auraGeneration;
		clearAll();

		if not (ALIVE and A.On) then return end;

		local character = LocalPlayer.Character;

		if not character then return end;

		task.defer(function()
		for _, name in ipairs(ORDER) do
			if A.Types[name] then
				local build = BUILDERS[name];

				if generation ~= auraGeneration or not ALIVE or not A.On or LocalPlayer.Character ~= character then return end;
				if build then
					local ok, err = pcall(build, character, generation);
					if not ok and generation == auraGeneration then A.LoadErrors[name] = tostring(err); recordError("aura " .. name .. ": " .. tostring(err)) end;
					if ok and generation == auraGeneration then A.ReadyTypes[name] = true; tune() end;
				end;
			end;
		end;

		tune();
		if Preview and Preview.ReadAura and ALIVE and generation == auraGeneration then pcall(Preview.ReadAura) end;
		end);
	end;

	local function onCharacterAdded()
		if not A.On then return end;

		task.wait(0.5);

		if ALIVE and A.On then refreshAuras() end;
	end;

	local function setEnabled(value)
		auraGeneration += 1;
		A.On = value and true or false;

		if A.On then
			if not charConnection then
				charConnection = NeverLose:AddSignal(LocalPlayer.CharacterAdded:Connect(onCharacterAdded));
			end;

			if LocalPlayer.Character then
				task.spawn(function()
					task.wait(0.2);

					if ALIVE and A.On then refreshAuras() end;
				end);
			end;
		else
			if charConnection then
				pcall(function() charConnection:Disconnect() end);

				charConnection = nil;
			end;

			clearAll();
		end;
	end;

	function A.Dress(player, names, colour)
		if not player or player == LocalPlayer then return end;

		local bank = guests[player];

		if not bank then bank = newBank(colour); guests[player] = bank end;

		bank.color = colour or bank.color;
		bank.want = names or {};
	end;

	function A.Undress(player)
		local bank = guests[player];

		if not bank then return end;

		clearBank(bank);
		guests[player] = nil;
	end;

	function A.Guests() return guests end;

	local function serveGuest(player, bank)
		local character = player.Character;

		if not character or not character.Parent then
			if bank.char then clearBank(bank); bank.char = nil end;
			return;
		end;

		local key = table.concat(bank.want, ",");

		if bank.char == character and bank.key == key then return end;

		clearBank(bank);
		bank.char, bank.key = character, key;

		for _, name in ipairs(bank.want) do
			local build = BUILDERS[name];

			if build and name ~= "Comet" then
				sink = bank;
				pcall(build, character, auraGeneration, bank);
				sink = mine;
			end;
		end;

		tuneBank(bank);
	end;

	task.spawn(function()
		while ALIVE do
			task.wait(0.5);

			for player, bank in pairs(guests) do
				if not player.Parent then A.Undress(player) else pcall(serveGuest, player, bank) end;
			end;
		end;
	end);

	onUnload("aura guests", function()
		for player in pairs(guests) do pcall(A.Undress, player) end;
	end);

	ESP.AuraSource = function()
		return LocalPlayer.Character;
	end;

	local function refreshPreview()
		if Preview and Preview.ReadAura then pcall(Preview.ReadAura) end;
	end;

	local row = Sections.Aura:AddLabel("Aura");

	row:AddToggle({
		Name = "Aura",
		Default = false,
		Flag = "aura",
		Callback = function(v) setEnabled(v); if A.WearGame then A.WearGame() end; refreshPreview() end,
	});

	row:AddColorPicker({
		Default = A.Color,
		Flag = "aura_color",
		Callback = function(v)
			A.Color = v;

			tune();
			refreshPreview();
		end,
	});

	local FX = ESP.GameFX;
	local gameIds = {};
	local ART = {
		Angelic = "rbxassetid://13267054240", Ambient = "rbxassetid://12713358087",
		Nimb = "rbxassetid://8819682608", Tornado = "rbxassetid://8553497052",
		Comet = "rbxassetid://11402221943",
	};

	local function auraRows()
		local out = {};

		for _, name in ipairs(ORDER) do
			local image, rect, size = ART[name], nil, nil;
			if FX then image, rect, size = FX.Art("builtin/aura/" .. name, ART[name]) end;
			out[#out + 1] = { name = name, label = name, image = image, rect = rect, rectsize = size,
				id = not rect and tonumber(CATALOGUE[name]) or nil };
		end;

		for _, entry in ipairs(FX and FX.Catalog or {}) do
			if entry.kind ~= "Trail" and entry.kind ~= "Cosmetic" then
				out[#out + 1] = FX.Row(entry);
			end;
		end;

		return out;
	end;

	function A.WearGame()
		if FX then FX.SetGroup("aura", A.On and gameIds or {}) end;
	end;

	local auraGrid = Visuals.Auras:AddGallery({
		Name = "Auras", Icon = "sparkles", Position = "left", Height = 440, Cell = 74, Reset = true, Smooth = true,
		Thumb = "Asset", Blank = "sparkles", Empty = "No auras", Values = auraRows(),
		Default = { "Angelic" }, Multi = true, Flag = "aura_types",
		Callback = function(v)
			local picked, game = {}, {};

			if type(v) == "table" then
				for key, value in pairs(v) do

					local name = (type(key) == "string" and value) and key or value;

					if type(name) == "string" then
						if BUILDERS[name] then picked[name] = true
						elseif FX and FX.ById[name] then game[#game + 1] = name end;
					end;
				end;
			elseif type(v) == "string" then
				picked[v] = true;
			end;

			gameIds = game;
			A.WearGame();
			A.Types = picked;
			A.Type = nil;

			for _, name in ipairs(ORDER) do
				if picked[name] then A.Type = name; break end;
			end;

			if not A.Type and next(picked) then A.Type = "Angelic" end;

			refreshAuras();
			refreshPreview();
		end,
	});
	Sections.Aura:AddButton({ Name = "Unequip All", Icon = "x", Callback = function()
		pcall(function() auraGrid:set({}) end);
	end });

	if FX then
		FX.OnThumbs(function() auraGrid:setdata(auraRows()) end);
		Visuals.Auras.Signal:Connect(function(open) if open then FX.LoadThumbs() end end);
	end;

	Sections.Aura:AddLabel("Custom Colors"):AddToggle({ Default = true, Flag = "aura_tint",
		Callback = function(v) A.Tint = v; tune(); refreshPreview() end });

	for _, setting in ipairs({
		{ "Glow", "Glow", "aura_glow", 0, 600, 200, 100 },
		{ "Rate", "Rate", "aura_rate", 10, 400, 100, 100 },
		{ "Size", "Size", "aura_size", 25, 300, 100, 100 },
		{ "Speed", "Speed", "aura_speed", 5, 500, 100, 100 },
	}) do
		local key, divisor = setting[2], setting[7];

		Sections.Aura:AddLabel(setting[1]):AddSlider({
			Min = setting[4], Max = setting[5], Default = setting[6],
			Rounding = 0, Size = 90, Flag = setting[3],
			Callback = function(v)
				A[key] = v / divisor;

				tune();
				refreshPreview();
			end,
		});
	end;

	ESP.ClearAura = onUnload("aura", function()
		A.On = false;
		if FX then pcall(FX.SetGroup, "aura", {}) end;
		auraGeneration += 1;

		if charConnection then
			pcall(function() charConnection:Disconnect() end);

			charConnection = nil;
		end;

		clearAll();
		hideComet();
		table.clear(cometSprites);
		for _, source in pairs(loaded) do if source then pcall(function() source:Destroy() end) end end;
		table.clear(loaded);
	end);
end);

guard("cosmetics", function()
	local FX = ESP.GameFX;
	if not FX then return end;

	local C = {
		On = true, Picked = {}, Color = Color3.fromRGB(255, 255, 255),
		Opacity = 1, Glow = 1, Rate = 1, Size = 1, Speed = 1,
		X = 0, Y = 0, Z = 0, TransformScale = 1,
	};
	ESP.Cosmetics = C;

	local function wear()
		FX.SetGroup("cosmetic", C.On and C.Picked or {});
	end;

	local function tune()
		FX.Tune("cosmetic", {
			opacity = C.Opacity, glow = C.Glow, rate = C.Rate, size = C.Size, speed = C.Speed,
			x = C.X, y = C.Y, z = C.Z, scale = C.TransformScale,
		});
	end;

	local function rows()
		local out = {};
		for _, entry in ipairs(FX.Catalog) do
			if entry.kind == "Cosmetic" then
				out[#out + 1] = FX.Row(entry);
			end;
		end;
		return out;
	end;

	local grid = Visuals.Cosmetics:AddGallery({
		Name = "Cosmetics", Icon = "crown", Position = "left", Height = 440, Cell = 74, Wrap = true, Reset = true, Smooth = true,
		Thumb = "Asset", Blank = "crown", Empty = "No cosmetics", Values = rows(),
		Multi = true, Flag = "cosmetic_pick",
		Callback = function(v)
			local picked = {};
			for key, value in pairs(type(v) == "table" and v or {}) do
				local name = (type(key) == "string" and value) and key or value;
				if type(name) == "string" and FX.ById[name] then picked[#picked + 1] = name end;
			end;
			C.Picked = picked;
			wear();
		end,
	});
	FX.OnThumbs(function() grid:setdata(rows()) end);
	Visuals.Cosmetics.Signal:Connect(function(open) if open then FX.LoadThumbs() end end);

	local row = Sections.Cosmetics:AddLabel("Enabled");
	row:AddToggle({ Default = true, Flag = "cosmetic", Callback = function(v) C.On = v; wear() end });
	row:AddColorPicker({ Default = C.Color, Flag = "cosmetic_color", Callback = function(v) C.Color = v; tune() end });

	for _, setting in ipairs({
		{ "Opacity", "Opacity", "cosmetic_opacity", 0, 100, 100 },
		{ "Glow", "Glow", "cosmetic_glow", 0, 300, 100 },
		{ "Particle Rate", "Rate", "cosmetic_rate", 0, 300, 100 },
		{ "Particle Size", "Size", "cosmetic_size", 25, 300, 100 },
		{ "Speed", "Speed", "cosmetic_speed", 5, 300, 100 },
	}) do
		local key = setting[2];
		Sections.Cosmetics:AddLabel(setting[1]):AddSlider({
			Min = setting[4], Max = setting[5], Default = setting[6], Type = "%", Size = 100, Flag = setting[3],
			Callback = function(v) C[key] = v / 100; tune() end,
		});
	end;

	for _, axis in ipairs({ "X", "Y", "Z" }) do
		Sections.CosmeticsXYZ:AddLabel(axis):AddSlider({
			Min = -5, Max = 5, Default = 0, Rounding = 1, Size = 100,
			Flag = "cosmetic_xyz_" .. string.lower(axis),
			Callback = function(v) C[axis] = v; tune() end,
		});
	end;
	Sections.CosmeticsXYZ:AddLabel("Size"):AddSlider({
		Min = 25, Max = 250, Default = 100, Type = "%", Rounding = 0, Size = 100,
		Flag = "cosmetic_xyz_size",
		Callback = function(v) C.TransformScale = v / 100; tune() end,
	});

	Sections.Cosmetics:AddButton({ Name = "Unequip All", Icon = "x", Callback = function()
		pcall(function() grid:set({}) end);
	end });

	ESP.ClearCosmetics = onUnload("cosmetics", function()
		pcall(FX.SetGroup, "cosmetic", {});
	end);
end);

guard("motiongraph", function()
	local MG = { On = false };

	ESP.MotionGraph = MG;

		local run = RunService
		local ws  = workspace
		local lp  = LocalPlayer

		local mg_on = false
		local mg_color = Color3.fromRGB(242, 242, 242)
		local mg_width = 280
		local mg_height = 72
		local mg_offset = 105
		local mg_thickness = 1
		local mg_span = 2.8
		local mg_step = 1 / 30
		local mg_accum = 0
		local mg_render_accum = 0
		local mg_smooth = 0
		local mg_history = {}
		local mg_lines = {}
		local mg_shadows = {}
		local mg_labels = {}
		local mg_current = nil
		local mg_conn = nil

		local function mg_remove(obj)
			destroyAny(obj)
		end

		local function mg_speed()
			local char = lp.Character
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if not root then return 0 end
			local velocity = root.AssemblyLinearVelocity
			return Vector3.new(velocity.X, 0, velocity.Z).Magnitude
		end

		local function mg_reference()
			local char = lp.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			return math.max(1, hum and hum.WalkSpeed or 16)
		end

		local function mg_new_line(color, thickness, zindex, transparency)
			local line = Drawing.new("Line")
			line.Color = color
			line.Thickness = thickness
			line.Transparency = transparency
			line.ZIndex = zindex
			line.Visible = false
			return line
		end

		local function mg_new_text()
			local text = Drawing.new("Text")
			text.Center = true
			text.Outline = true
			text.Color = mg_color
			text.Size = 12
			text.ZIndex = 904
			text.Visible = false
			return text
		end

		local function mg_sync_pool(needed)
			while #mg_lines < needed do
				mg_shadows[#mg_shadows + 1] = mg_new_line(Color3.new(0, 0, 0), mg_thickness + 2, 901, 0.45)
				mg_lines[#mg_lines + 1] = mg_new_line(mg_color, mg_thickness, 902, 1)
			end
			while #mg_lines > needed do
				mg_remove(table.remove(mg_lines))
				mg_remove(table.remove(mg_shadows))
			end
		end

		local function mg_create()
			if mg_current then return end
			mg_current = mg_new_text()
			mg_current.Center = false
			for i = 1, 6 do
				mg_labels[i] = mg_new_text()
			end
		end

		local function mg_hide()
			if mg_current then mg_current.Visible = false end
			for i = 1, #mg_lines do
				mg_lines[i].Visible = false
				mg_shadows[i].Visible = false
			end
			for i = 1, #mg_labels do
				mg_labels[i].Visible = false
			end
		end

		local function mg_clear()
			if mg_conn then
				pcall(function() mg_conn:Disconnect() end)
				mg_conn = nil
			end
			mg_remove(mg_current)
			mg_current = nil
			for i = 1, #mg_lines do
				mg_remove(mg_lines[i])
				mg_remove(mg_shadows[i])
			end
			for i = 1, #mg_labels do
				mg_remove(mg_labels[i])
			end
			table.clear(mg_lines)
			table.clear(mg_shadows)
			table.clear(mg_labels)
			table.clear(mg_history)
			mg_accum = 0
			mg_render_accum = 0
		end

		local function mg_reset_history()
			table.clear(mg_history)
			local now = os.clock()
			local speed = mg_speed()
			mg_smooth = speed
			local count = math.ceil(mg_span / mg_step)
			for i = 0, count do
				mg_history[#mg_history + 1] = {
					t = now - mg_span + i * mg_step,
					v = speed
				}
			end
			mg_sync_pool(#mg_history)
		end

		local function mg_apply_style()
			if mg_current then mg_current.Color = mg_color end
			for i = 1, #mg_lines do
				mg_lines[i].Color = mg_color
				mg_lines[i].Thickness = mg_thickness
				mg_shadows[i].Thickness = mg_thickness + 2
			end
			for i = 1, #mg_labels do
				mg_labels[i].Color = mg_color
			end
		end

		local function mg_y(value, center, height, reference)
			local normalized = math.clamp(value / reference - 1, -1, 1)
			return center - normalized * height * 0.44
		end

		local function mg_render(now)
			local camera = ws.CurrentCamera
			if not mg_on or not camera or #mg_history < 2 then
				mg_hide()
				return
			end
			local viewport = camera.ViewportSize
			local width = math.min(mg_width, math.max(120, viewport.X - 48))
			local height = math.min(mg_height, math.max(36, viewport.Y - 32))
			local left = math.floor(viewport.X * 0.5 - width * 0.5)
			local center = math.clamp(math.floor(viewport.Y * 0.5 + mg_offset), height * 0.5 + 8, viewport.Y - height * 0.5 - 8)
			local reference = mg_reference()
			local start_time = now - mg_span
			local count = #mg_history
			mg_sync_pool(count)
			for i = 1, count - 1 do
				local a = mg_history[i]
				local b = mg_history[i + 1]
				local ap = math.clamp((a.t - start_time) / mg_span, 0, 1)
				local bp = math.clamp((b.t - start_time) / mg_span, 0, 1)
				local fade = math.clamp(math.min((ap + bp) * 6, (2 - ap - bp) * 5), 0, 1)
				local from = Vector2.new(left + ap * width, mg_y(a.v, center, height, reference))
				local to = Vector2.new(left + bp * width, mg_y(b.v, center, height, reference))
				local line = mg_lines[i]
				local shadow = mg_shadows[i]
				line.From, line.To = from, to
				line.Transparency = fade
				line.Visible = fade > 0.02
				shadow.From, shadow.To = from, to
				shadow.Transparency = fade * 0.42
				shadow.Visible = fade > 0.02
			end
			local last = mg_history[count]
			local lpct = math.clamp((last.t - start_time) / mg_span, 0, 1)
			local from = Vector2.new(left + lpct * width, mg_y(last.v, center, height, reference))
			local to = Vector2.new(left + width, mg_y(mg_smooth, center, height, reference))
			local tail = mg_lines[count]
			local tail_shadow = mg_shadows[count]
			tail.From, tail.To = from, to
			tail.Transparency = 0.72
			tail.Visible = true
			tail_shadow.From, tail_shadow.To = from, to
			tail_shadow.Transparency = 0.3
			tail_shadow.Visible = true
			for i = count + 1, #mg_lines do
				mg_lines[i].Visible = false
				mg_shadows[i].Visible = false
			end
			mg_current.Text = tostring(math.floor(mg_smooth + 0.5))
			mg_current.Position = Vector2.new(left + width + 5, to.Y - 7)
			mg_current.Color = mg_color
			mg_current.Visible = true
			while #mg_labels < 12 do
				mg_labels[#mg_labels + 1] = mg_new_text()
			end
			local threshold = math.max(0.8, reference * 0.08)
			local min_label_gap = 0.42
			for i = 5, count - 4 do
				local point = mg_history[i]
				if not point.checked then
					point.checked = true
					local before = point.v - mg_history[i - 4].v
					local after = mg_history[i + 4].v - point.v
					if math.abs(before) >= threshold and (before * after <= 0 or math.abs(after) < threshold * 0.35) then
						local nearby = nil
						for j = i - 1, 1, -1 do
							local previous = mg_history[j]
							if point.t - previous.t > min_label_gap then break end
							if previous.label ~= nil then
								nearby = previous
								break
							end
						end
						local score = math.abs(before) - math.abs(after)
						if not nearby then
							point.label = math.floor(point.v + 0.5)
							point.label_score = score
						elseif score > (nearby.label_score or -math.huge) then
							nearby.label = nil
							nearby.label_score = nil
							point.label = math.floor(point.v + 0.5)
							point.label_score = score
						end
					end
				end
			end
			for i = 1, #mg_labels do
				mg_labels[i].Visible = false
			end
			local placed = {}
			local label_count = 0
			for i = count, 1, -1 do
				local point = mg_history[i]
				if point.label ~= nil and label_count < #mg_labels then
					local pct = (point.t - start_time) / mg_span
					if pct > 0.04 and pct < 0.82 then
						local value = tostring(point.label)
						local x = left + pct * width
						local y = mg_y(point.v, center, height, reference) - 15
						local half_width = math.max(8, #value * 3.5 + 2)
						local blocked = false
						for j = 1, #placed do
							local other = placed[j]
							if x + half_width + 5 > other.x1 and x - half_width - 5 < other.x2 and y + 13 > other.y1 and y - 3 < other.y2 then
								blocked = true
								break
							end
						end
						if not blocked then
							label_count = label_count + 1
							local text = mg_labels[label_count]
							text.Text = value
							text.Position = Vector2.new(x, y)
							text.Color = mg_color
							text.Visible = true
							placed[#placed + 1] = {
								x1 = x - half_width,
								x2 = x + half_width,
								y1 = y - 3,
								y2 = y + 13
							}
						end
					end
				end
			end
		end

		mg_offset = 180

		local function mg_start()
			mg_clear()
			mg_create()
			mg_reset_history()
			mg_apply_style()
			mg_conn = run.RenderStepped:Connect(function(dt)
				if not ALIVE or not mg_on then
					mg_hide()
					return
				end
				local raw = mg_speed()
				mg_smooth = mg_smooth + (raw - mg_smooth) * (1 - math.exp(-dt * 18))
				mg_accum = mg_accum + dt
				local now = os.clock()
				if mg_accum >= mg_step then
					mg_accum = mg_accum % mg_step
					mg_history[#mg_history + 1] = { t = now, v = mg_smooth }
					local cutoff = now - mg_span
					while #mg_history > 2 and mg_history[2].t < cutoff do
						table.remove(mg_history, 1)
					end
				end
				mg_render_accum += dt
				if mg_render_accum >= 1 / 60 then
					mg_render_accum %= 1 / 60
					mg_render(now)
				end
			end)
		end

		MG.On = false
		MG.Color     = mg_color
		MG.Width     = mg_width
		MG.Height    = mg_height
		MG.Thickness = mg_thickness
		MG.OffsetY   = mg_offset

		ESP.MotionGraphSet = { set = function(k, v)
			if k == "color" then
				mg_color = v
				mg_apply_style()
			elseif k == "width" then
				mg_width = v
			elseif k == "height" then
				mg_height = v
			elseif k == "y" then
				mg_offset = v
			elseif k == "thickness" then
				mg_thickness = v
				mg_apply_style()
			end
			MG.Color, MG.Width, MG.Height, MG.OffsetY, MG.Thickness = mg_color, mg_width, mg_height, mg_offset, mg_thickness
		end }

		ESP.StartMotionGraph = function()
			mg_on = true
			MG.On = true
			mg_start()
		end

		ESP.ClearMotionGraph = function()
			mg_on = false
			MG.On = false
			mg_clear()
		end

		ESP.MotionGraphStyle = mg_apply_style

		NeverLose:AddSignal(lp.CharacterAdded:Connect(function()
			task.wait(0.4)
			if ALIVE and mg_on then mg_reset_history() end
		end))

	local row = Sections.Screen:AddLabel("Motion Graph");
	row:AddToggle({
		Default = false, Flag = "motion_graph",
		Callback = function(v)
			if v then ESP.StartMotionGraph() else ESP.ClearMotionGraph() end;
		end,
	});
	row:AddColorPicker({
		Default = MG.Color, Flag = "motion_graph_color",
		Callback = function(v) ESP.MotionGraphSet.set("color", v) end,
	});

	local options = row:AddOption(1);

	options:AddLabel("Width"):AddSlider({
		Min = 120, Max = 600, Default = 280, Rounding = 0, Size = 90,
		Flag = "motion_graph_width",
		Callback = function(v) ESP.MotionGraphSet.set("width", v) end,
	});

	options:AddLabel("Height"):AddSlider({
		Min = 30, Max = 200, Default = 72, Rounding = 0, Size = 90,
		Flag = "motion_graph_height",
		Callback = function(v) ESP.MotionGraphSet.set("height", v) end,
	});

	options:AddLabel("Offset"):AddSlider({
		Min = 40, Max = 400, Default = 180, Rounding = 0, Size = 90,
		Flag = "motion_graph_offset",
		Callback = function(v) ESP.MotionGraphSet.set("y", v) end,
	});

	options:AddLabel("Thickness"):AddSlider({
		Min = 1, Max = 5, Default = 1, Rounding = 0, Size = 90,
		Flag = "motion_graph_thickness",
		Callback = function(v) ESP.MotionGraphSet.set("thickness", v) end,
	});
end);

guard("backtrack", function()
	local BT = {
		On = false,
		Style = "ForceField",
		Delay = 120,
		Color = Color3.fromRGB(120, 200, 255),
		Transparency = 45,
		Target = "Other",
		Outline = Color3.fromRGB(255, 255, 255),
		OutlineTransparency = 10,
		OutlineOn = true,
	};

	BT.ChamsMaterial = BT.Style;
	BT.ChamsOutline = BT.Outline;
	BT.ChamsOutlineTransparency = BT.OutlineTransparency;

	ESP.Backtrack = BT;

	local order = ESP.MaterialOrder;

	if type(order) ~= "table" or #order == 0 then
		order = {};

		for name in pairs(ESP.MaterialStyles or {}) do order[#order + 1] = name end;

		table.sort(order);
